#define _POSIX_C_SOURCE 200809L
#include <time.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
int main(void) {
    int p; long long n, x, start=0;
    if (scanf("%d %lld %lld %lld", &p, &n, &x, &start)<3) return 2;
    if(start>0){
        struct timespec t;clock_gettime(CLOCK_REALTIME,&t);
        long long delay=start-((long long)t.tv_sec*1000+t.tv_nsec/1000000);
        if(delay>0){struct timespec wait={delay/1000,(delay%1000)*1000000};while(nanosleep(&wait,&wait)!=0){}}
        clock_gettime(CLOCK_REALTIME,&t);
        if((long long)t.tv_sec*1000+t.tv_nsec/1000000-start>500){fprintf(stderr,"BENCHMARK_BARRIER_MISSED");return 9;}
    }
    long long out=0;
    const int size=4194304, mask=size-1;
    if(p==0) {
        for(long long i=0;i<n;i++) out+=i%97;
    } else if(p==1) {
        for(long long i=0;i<n;i++) x=(x*1664525+1013904223)%1000000007;
        out=x;
    } else if(p==2 || p==3) {
        uint32_t *a=(uint32_t*)malloc((size_t)size*sizeof(uint32_t));
        if(!a) return 3;
        for(int i=0;i<size;i++) a[i]=(uint32_t)(((long long)i*1664525+1013904223)&mask);
        if(p==2) {
            for(long long i=0;i<n;i++) out+=a[i&mask];
            out%=1000000007;
        } else {
            x&=mask;
            for(long long i=0;i<n;i++) x=a[x];
            out=x;
        }
        free(a);
    } else if(p==4) {
        const int m=1048576;
        uint32_t *a=(uint32_t*)malloc((size_t)m*sizeof(uint32_t));
        if(!a) return 3;
        for(int i=0;i<m;i++) a[i]=(uint32_t)(2*i+1);
        for(long long i=0;i<n;i++){
            x=(x*1664525+1013904223)&(2*m-1);
            int lo=0, hi=m;
            while(lo<hi){int mid=(lo+hi)/2; if(a[mid]<x)lo=mid+1;else hi=mid;}
            out+=lo;
        }
        out%=1000000007; free(a);
    } else if(p==5) {
        for(long long i=0;i<n;i++) {
            x=(x*1103515245+12345)&2147483647;
            if(x&1024) out+=x%97; else out^=x&65535;
            out&=2147483647;
        }
    } else return 4;
    printf("%lld\n",out);
    return 0;
}

